  const njs = (t) => t.replace(/\/\*[\s\S]*?\*\//g, '').replace(/^\s*\/\/[^\n]*/gm, '');   // loop C-5: JS pins track CODE shape, not comments
  const av370 = njs(read('src/components/avatar.js'));
