    const v0 = '1BvNvvJTfDNhx8pDJfTZFjSVLnwFsWtWCH4bDZLRoMFtxSJR';   // 48 — the SHORTEST real address
    const v1 = '4rNvvJTfDNhx8pDJfTZFjSVLnwFsWtWCH4bDZLRoMFtxSJRfnKZqfg5Q8V5YqWzLm';   // 65 — v1/v2 encode to EXACTLY this
